// (1) EXTEND Thread (works, but ties you to a single execution).
class MyThread extends Thread {
  public void run() { System.out.println("running on " + getName()); }
}
new MyThread().start();

// (2) IMPLEMENT Runnable (PREFERRED: task separate from execution).
Runnable task = () -> System.out.println("running on " + Thread.currentThread());
new Thread(task).start();

// (3) PRACTICE: use an ExecutorService (pools threads, don't create directly).
ExecutorService pool = Executors.newFixedThreadPool(4);
pool.submit(task);                 // reuse a pooled thread
pool.submit(task);
pool.shutdown();                   // always shut down

// (4) MODERN: virtual threads (Project Loom) for lightweight I/O concurrency.
Thread.startVirtualThread(task);   // millions of cheap threads
